// -----------------------------------------------------------------------------
// tb_stap_pi_filter.v - self-checking-by-file testbench for stap_pi_filter.
//
// Inputs (generated by python/tests/test_rtl.py or python/gen_rtl_vectors.py):
//   tb_in.hex : 4 words per sample  x0_re x0_im x1_re x1_im   (IW bits each)
//   tb_w.hex  : 2*D words per block  w0_re w0_im w1_re ...    (WW bits each)
// Output:
//   tb_out.txt: one "re im" line per output sample (signed decimal)
//
// Weights of block b+1 are written to the shadow bank during the first D
// samples of block b; w_commit is asserted with the first sample of each
// block, exactly like the firmware/PS interface would do it.
// GAP = 1 inserts an idle clock between samples (sample rate = clk / 2).
// -----------------------------------------------------------------------------
`timescale 1ns / 1ps

module tb_stap_pi_filter;
    parameter integer N_EL      = 2;
    parameter integer N_TAPS    = 7;
    parameter integer IW        = 16;
    parameter integer WW        = 18;
    parameter integer OW        = 16;
    parameter integer SW        = 6;
    parameter integer NS        = 4096;   // samples
    parameter integer NB        = 4;      // weight blocks
    parameter integer BLOCK     = 1024;   // samples per block
    parameter integer OUT_SHIFT = 10;
    parameter integer GAP       = 0;

    localparam integer D = N_EL * N_TAPS;

    reg clk = 1'b0;
    always #2.5 clk = ~clk;

    reg                    rst = 1'b1;
    reg                    in_valid = 1'b0;
    reg  [N_EL*IW-1:0]     in_re = 0, in_im = 0;
    reg                    w_we = 1'b0, w_commit = 1'b0;
    reg  [7:0]             w_addr = 0;
    reg  signed [WW-1:0]   w_re = 0, w_im = 0;
    wire                   out_valid;
    wire signed [OW-1:0]   out_re, out_im;

    stap_pi_filter #(.N_EL(N_EL), .N_TAPS(N_TAPS), .IW(IW), .WW(WW), .OW(OW), .SW(SW)) dut (
        .clk(clk), .rst(rst),
        .in_valid(in_valid), .in_re(in_re), .in_im(in_im),
        .w_we(w_we), .w_addr(w_addr), .w_re(w_re), .w_im(w_im), .w_commit(w_commit),
        .out_shift(OUT_SHIFT[SW-1:0]),
        .out_valid(out_valid), .out_re(out_re), .out_im(out_im)
    );

    reg [IW-1:0] xmem [0:N_EL*2*NS-1];
    reg [WW-1:0] wmem [0:2*D*NB-1];
    integer fd, n, i, m, b, j, n_out;

    // ------------------------------------------------------------- capture
    initial n_out = 0;
    always @(posedge clk) begin
        if (out_valid) begin
            $fwrite(fd, "%0d %0d\n", out_re, out_im);
            n_out = n_out + 1;
        end
    end

    // ------------------------------------------------------------- stimulus
    initial begin
        $readmemh("tb_in.hex", xmem);
        $readmemh("tb_w.hex", wmem);
        fd = $fopen("tb_out.txt", "w");

        repeat (4) @(negedge clk);
        rst = 1'b0;

        // preload block 0 into the shadow bank
        for (i = 0; i < D; i = i + 1) begin
            @(negedge clk);
            w_we = 1'b1; w_addr = i; w_re = wmem[2 * i]; w_im = wmem[2 * i + 1];
        end
        @(negedge clk);
        w_we = 1'b0;

        for (n = 0; n < NS; n = n + 1) begin
            @(negedge clk);
            b = n / BLOCK;
            j = n % BLOCK;
            in_valid = 1'b1;
            for (m = 0; m < N_EL; m = m + 1) begin
                in_re[m * IW +: IW] = xmem[N_EL * 2 * n + 2 * m];
                in_im[m * IW +: IW] = xmem[N_EL * 2 * n + 2 * m + 1];
            end
            w_commit = (j == 0);
            if ((j < D) && (b + 1 < NB)) begin
                w_we = 1'b1; w_addr = j;
                w_re = wmem[2 * ((b + 1) * D + j)];
                w_im = wmem[2 * ((b + 1) * D + j) + 1];
            end else begin
                w_we = 1'b0;
            end
            if (GAP != 0) begin
                @(negedge clk);
                in_valid = 1'b0; w_we = 1'b0; w_commit = 1'b0;
            end
        end
        @(negedge clk);
        in_valid = 1'b0; w_we = 1'b0; w_commit = 1'b0;

        repeat (10) @(negedge clk);
        if (n_out != NS) $display("ERROR: expected %0d outputs, got %0d", NS, n_out);
        else             $display("tb_stap_pi_filter: %0d outputs written", n_out);
        $fclose(fd);
        $finish;
    end
endmodule
